17	namespace Atvoss::Tile {
18	
19	template <typename T>
20	using Dtype_t = typename T::Type::PrimType;
21	
22	// Primary template
23	template <typename T>
24	struct Evaluator {
25	    using Type = T;
26	
27	    template <typename Context>
28	    __aicore__ inline decltype(auto) operator()(const T& value, Context& /*context*/) const
29	    {
30	        return value;
31	    }
32	};
33	
34	// Treat Evaluator<Expression<T>> as Evaluator<T>
35	template <typename T>
36	struct Evaluator<Expression<T>> : Evaluator<T> {};
37	
38	// Partial specialization for LocalVar
39	template <std::size_t N, typename T, typename L>
40	struct Evaluator<LocalVar<N, T, L>> {
41	    using Type = T;
42	
43	    template <typename Context>
44	    __aicore__ inline decltype(auto) operator()(LocalVar<N, T, L> /*unused*/, Context& context) const
45	    {
46	        static_assert(N > 0, "[ERROR]: [Atvoss][Tile] LocalVar number starts from 1");
47	        return AscendC::Std::get<N - 1>(context.tmpTensors);
48	    }
49	};
50	
51	// Partial specialization for Param
52	template <std::size_t N, typename T, ParamUsage U, std::size_t R>
53	struct Evaluator<Param<N, T, U, R>> {
54	    using Type = T;
55	
56	    template <typename Context>
57	    __aicore__ inline decltype(auto) operator()(Param<N, T, U, R> /*unused*/, Context& context) const
58	    {
59	        static_assert(N > 0, "[ERROR]: [Atvoss][Tile] Param number starts from 1");
60	        constexpr auto index = N - 1;
61	        using ArgsTensors = decltype(context.argsTensors);
62	        using NthType = typename AscendC::Std::tuple_element<index, std::remove_reference_t<ArgsTensors>>::type;
63	        if constexpr (std::is_same_v<T, NthType> || std::is_same_v<T&, NthType> || std::is_same_v<T&&, NthType>) {
64	            return AscendC::Std::get<index>(context.argsTensors);
65	        } else {
66	            static_assert(
67	                U == ParamUsage::IN, "[ERROR]: [Atvoss][Tile] Only in-parameters allow implicit type conversions");
68	            return static_cast<T>(AscendC::Std::get<index>(context.argsTensors));
69	        }
70	    }
71	};
72	
73	template <typename T, typename U>
74	struct Evaluator<OpAssign<T, U>> {
75	    using Type = void;
76	
77	    template <typename Context>
78	    __aicore__ inline void operator()(const OpAssign<T, U>& op, Context& context) const
79	    {
80	        return Assign(Evaluator<T>{}(op.GetLhs(), context), Evaluator<U>{}(op.GetRhs(), context));
81	    }
82	};
83	
84	// Partial specializtion for E_x, E_y
85	template <typename T, typename U>
86	struct Evaluator<OpAndThen<T, U>> {
87	    using Type = typename Evaluator<U>::Type;
88	
89	    template <typename Context>
90	    __aicore__ inline Type operator()(const OpAndThen<T, U>& op, Context& context) const
91	    {
92	        // operator, evaluates sequentially
93	        AscendC::PipeBarrier<PIPE_V>();
94	        return Atvoss::Tile::Evaluator<T>{}(op.GetLhs(), context), Atvoss::Tile::Evaluator<U>{}(op.GetRhs(), context);
95	    }
96	};
97	
98	template <typename Fun, class... Args>
99	constexpr __aicore__ inline void Assign(Fun& fun_, Args... args)
100	{
101	    fun_(args...);
102	}
103	
104	template <typename T, typename U>
105	__aicore__ inline void Assign(T& dst, const U& src)
106	{
107	    dst = src;
108	}
109	
110	} // namespace Atvoss::Tile
111	#endif // ATVOSS_TILE_EVALUATOR_BASE_H
