59	// Partial specialization for CopyIn(E)
60	template <typename T>
61	struct Evaluator<OpCopyIn<T>> {
62	    using Type = void;
63	
64	    template <typename Context>
65	    __aicore__ inline auto operator()(const OpCopyIn<T>& op, Context& context) const
66	    {
67	        auto& obj = Evaluator<T>{}(op.GetData(), context);
68	        uint32_t bufferId =
69	            Atvoss::Ele::Tile::GetBufferId<typename Context::BuffMaps, T::number, Atvoss::Ele::Tile::BufType::PARAM>(
70	                context.pingPong);
71	        // AscendC::printf("OpCopyIn, IN[%u]-[%u] context.pingPong: %u\n", T::number, bufferId, context.pingPong);
72	#if _ATVOSS_ARCH35_
73	        AscendC::Mutex::Lock<PIPE_MTE2>(bufferId);
74	#else
75	        AscendC::PipeBarrier<PIPE_ALL>();
76	#endif
77	        obj.CopyIn(context.gmOffset, context.elementNum);
78	#if _ATVOSS_ARCH35_
79	        AscendC::Mutex::Unlock<PIPE_MTE2>(bufferId);
80	        AscendC::Mutex::Lock<PIPE_V>(bufferId);
81	#else
82	        AscendC::PipeBarrier<PIPE_ALL>();
83	#endif
84	    }
85	};
