88	template <typename T>
89	struct Evaluator<OpCopyOut<T>> {
90	    using Type = void;
91	
92	    template <typename Context>
93	    __aicore__ inline auto operator()(const OpCopyOut<T>& op, Context& context) const
94	    {
95	        uint32_t bufferId =
96	            Atvoss::Ele::Tile::GetBufferId<typename Context::BuffMaps, T::number, Atvoss::Ele::Tile::BufType::PARAM>(
97	                context.pingPong);
98	        // AscendC::printf("OpCopyIn, IN[%u]-[%u] context.pingPong: %u\n", T::number, bufferId, context.pingPong);
99	#if _ATVOSS_ARCH35_
100	        AscendC::Mutex::Unlock<PIPE_V>(bufferId);
101	        AscendC::Mutex::Lock<PIPE_MTE3>(bufferId);
102	#else
103	        AscendC::PipeBarrier<PIPE_ALL>();
104	#endif
105	        auto& obj = Evaluator<T>{}(op.GetData(), context);
106	        obj.CopyOut(context.gmOffset, context.elementNum);
107	#if _ATVOSS_ARCH35_
108	        AscendC::Mutex::Unlock<PIPE_MTE3>(bufferId);
109	#else
110	        AscendC::PipeBarrier<PIPE_ALL>();
111	#endif
112	    }
113	};
