134	template <typename T>
135	struct Evaluator<OpAlloc<T>> {
136	    using Type = void;
137	
138	    template <typename Context>
139	    __aicore__ inline auto operator()(const OpAlloc<T>& op, Context& context) const
140	    {
141	        // T x = 0;
142	        if constexpr (!std::is_scalar_v<typename T::Type>) {
143	            auto& obj = Evaluator<T>{}(op.GetData(), context);
144	
145	            if constexpr (!HasUsage<T>{}) { // tmp param
146	                uint32_t tmpId = Atvoss::Ele::Tile::GetBufferId<
147	                    typename Context::BuffMaps, T::number, Atvoss::Ele::Tile::BufType::LOCAL_VAR>(context.pingPong);
148	                // AscendC::printf("OpAlloc, LOCAL_VAR[%u]-[%u] context.pingPong: %u\n", T::number, tmpId,
149	                // context.pingPong);
150	                context.bufPools.AllocTensor(obj.GetUbTensor(), tmpId);
151	#if _ATVOSS_ARCH35_
152	                AscendC::Mutex::Lock<PIPE_V>(tmpId);
153	#else
154	                AscendC::PipeBarrier<PIPE_ALL>();
155	#endif
156	                return;
157	            } else if constexpr (
158	                HasUsage<T>{} && T::usage == Atvoss::ParamUsage::IN ||
159	                T::usage == Atvoss::ParamUsage::IN_OUT) { // in param: need copy in
160	                uint32_t inId = Atvoss::Ele::Tile::GetBufferId<
161	                    typename Context::BuffMaps, T::number, Atvoss::Ele::Tile::BufType::PARAM>(context.pingPong);
162	                context.bufPools.AllocTensor(obj.GetUbTensor(), inId);
163	                return;
164	            } else if constexpr (HasUsage<T>{} && T::usage == Atvoss::ParamUsage::OUT) { // out param
165	                uint32_t outId = Atvoss::Ele::Tile::GetBufferId<
166	                    typename Context::BuffMaps, T::number, Atvoss::Ele::Tile::BufType::PARAM>(context.pingPong);
167	                context.bufPools.AllocTensor(obj.GetUbTensor(), outId);
168	#if _ATVOSS_ARCH35_
169	                AscendC::Mutex::Lock<PIPE_V>(outId);
170	#else
171	                AscendC::PipeBarrier<PIPE_ALL>();
172	#endif
173	                return;
174	            }
175	        }
176	    }
177	};
