220	// Check whether @ToCheckOp can be free
221	// (not used since @start in @OpList any more)
222	template <typename OpLst, typename ToCheckOp, bool cacheBrc, std::size_t start>
223	__host_aicore__ constexpr bool IsAbleToFree()
224	{
225	    if constexpr (IsCacheBind_v<cacheBrc, ToCheckOp>) {
226	        return false;
227	    } else if constexpr (start < Size_v<OpLst>) {
228	        using Op = Get_t<OpLst, start>;
229	        using InputOps = typename Op::InNonScalarOps;
230	        if constexpr (Contains_v<InputOps, ToCheckOp>) {
231	            return false;
232	        }
233	        return IsAbleToFree<OpLst, ToCheckOp, cacheBrc, start + 1>();
234	    } else {
235	        return true;
236	    }
237	}
