240	struct Bind {
241	private:
242	    using Pattern = OpPattern<OpX>;
243	
244	public:
245	    // Param<> or LocalVar<>
246	    using AssignedTo = V;
247	    // OpX<...>
248	    using Operation = typename Pattern::OpTpl;
249	    using BindType = Bind<V, Operation>;
250	    using TensorType = typename Operation::TensorType;
251	    using RetType = typename Operation::RetType;
252	    // Arguments except values.
253	    // Exp: in OpReduceSum<AR, ...>, AR will be removed.
254	    using OpArgs = typename Pattern::OpArgs;
255	    // Input & Outpu GM Params in OpArgs
256	    using AllParams = Unique_t<Filter_t<IsParam, OpArgs>>;
257	    // Input GM Params in OpArgs
258	    using InParams = Filter_t<IsInParam, AllParams>;
259	    // Output GM Params in OpArgs
260	    using OutParams = Filter_t<IsOutParam, AllParams>;
261	
262	private:
263	    // InOps in OpArgs by filter In/Out GM & scalar type like float/bool/int/enum...
264	    using InOpsTmp1 = Unique_t<Difference_t<OpArgs, AllParams>>;
265	    using InOpsTmp2 = Filter_t<std::is_scalar, InOpsTmp1>;
266	
267	public:
268	    using InOps = Difference_t<InOpsTmp1, InOpsTmp2>;
269	    // TODO: InScalarParams
270	    // TODO: InScalarOps & InNonScalarOps
271	    using InScalarOps = Filter_t<IsScalarBind, InOps>;
272	    using InNonScalarOps = Difference_t<InOps, InScalarOps>;
273	    // dependencies & self
274	    using DependOps = Append_t<Unique_t<decltype(ForEach(InOps{}, ExtractDependOps{}, TypeList<>{}))>, BindType>;
275	    // TODO
276	    constexpr static bool isScalarOp = false;
277	    constexpr static bool isCopyXOp =
278	        (IsSpecializationOf_v<OpCopyIn, Operation> || IsSpecializationOf_v<OpCopyOut, Operation>);
279	    constexpr static bool isCopyInOp = IsSpecializationOf_v<OpCopyIn, Operation>;
280	};
