192	// Replace Params with Usage=InOut to new Params with Usage=Out.
193	template <
194	    typename InplaceParams, typename ReplaceMap, typename ExprList, std::size_t nextParamNum,
195	    std::size_t pos = Size_v<ExprList> - 1>
196	__host_aicore__ constexpr decltype(auto) ReplaceInplaceParam()
197	{
198	    if constexpr (Size_v<InplaceParams> == 0) {
199	        return ExprList{};
200	    } else {
201	        using AssignExpr = Get_t<ExprList, pos>;
202	        using AssignLhs = typename AssignExpr::LhsType;
203	        using AssignRhs = typename AssignExpr::RhsType;
204	        if constexpr (Contains_v<InplaceParams, AssignLhs>) {
205	            using Pm = Filter_t<InplaceParamEqual<AssignLhs>::template Type, ReplaceMap>;
206	            static_assert(Size_v<Pm> == 1, "BUG");
207	            using NewLhs = Get_t<First_t<Pm>, 1>;
208	            using InplaceParamsNext = Difference_t<InplaceParams, TypeList<AssignLhs>>;
209	            using ReplaceMapNext = Difference_t<ReplaceMap, Pm>;
210	            using NewRhs =
211	                ReplaceOpArgs_t<AssignRhs, InplaceParamReplaceFinder<ReplaceMapNext, InplaceParamsNext>::template Type>;
212	            using NewAssign = OpAssign<NewLhs, NewRhs>;
213	            using ExprListNext = Set_t<ExprList, pos, NewAssign>;
214	            return ReplaceInplaceParam<InplaceParamsNext, ReplaceMapNext, ExprListNext, nextParamNum + 1, pos - 1>();
215	        } else {
216	            using NewRhs =
217	                ReplaceOpArgs_t<AssignRhs, InplaceParamReplaceFinder<ReplaceMap, InplaceParams>::template Type>;
218	            using NewAssign = OpAssign<AssignLhs, NewRhs>;
219	            using ExprListNext = Set_t<ExprList, pos, NewAssign>;
220	            return ReplaceInplaceParam<InplaceParams, ReplaceMap, ExprListNext, nextParamNum + 1, pos - 1>();
221	        }
222	    }
223	}
