263	private:
264	    using OriAllParams = Params_t<ExprList>;
265	    using InplaceParams = Filter_t<IsInplaceVar, OriAllParams>;
266	    using AssignedInplaceParams =
267	        Unique_t<decltype(ForEach(ExprList{}, ExtractAssignedParams<ParamUsage::IN_OUT>{}, TypeList<>{}))>;
268	    using ReplaceParamsMap =
269	        decltype(CreateReplacerForInplaceParams<AssignedInplaceParams, Size_v<OriAllParams> + 1>());
270	    using NewExprListTmp =
271	        decltype(ReplaceInplaceParam<AssignedInplaceParams, ReplaceParamsMap, ExprList, Size_v<OriAllParams> + 1>());
272	
273	public:
274	    using Type = decltype(ChangeInplaceParamUsageToIn<InplaceParams, NewExprListTmp>());
275	};
