343	template <
344	    const int32_t* const* bufIds, typename BindLst, typename OutBindLst,
345	    /* Needs to update during each loop below */
346	    typename AssignLst = TypeList<>,                                         /* return */
347	    typename Bind2ParamMap = TypeList<>, typename Param2BufMap = TypeList<>, /* return */
348	    typename BufId2ParamMap = TypeList<>, std::size_t pos = 0, std::size_t localVarIdx = 1>
349	__host_aicore__ constexpr decltype(auto) Bind2OpAssign()
350	{
351	    if constexpr (pos < Size_v<BindLst>) {
352	        using B = Get_t<BindLst, pos>;
353	        using ParamX = typename B::AssignedTo;
354	        using Operation = typename B::Operation;
355	        constexpr auto pingId = bufIds[0][pos];
356	        constexpr auto pongId = bufIds[1][pos];
357	        if constexpr (B::isCopyXOp) {
358	            if constexpr (B::isCopyInOp) {
359	                using AssignLstNext = Append_t<AssignLst, Operation>;
360	                using Bind2ParamMapNext = Prepend_t<TypeList<B, ParamX>, Bind2ParamMap>;
361	                constexpr auto paramIdx = ParamX::number;
362	                using Param2BufMapNext =
363	                    Append_t<Param2BufMap, ParamBufIdMap<paramIdx, BufType::PARAM, pingId, pongId>>;
364	                using BufId2ParamMapNext = typename UpdateBufId2Param<BufId2ParamMap, pingId, ParamX>::Type;
365	                return Bind2OpAssign<
366	                    bufIds, BindLst, OutBindLst, AssignLstNext, Bind2ParamMapNext, Param2BufMapNext, BufId2ParamMapNext,
367	                    pos + 1, localVarIdx>();
368	            } else { // CopyOut
369	                using NewCopyOut = ReplaceOpArgs_t<Operation, BindAssignedToFinder<Bind2ParamMap>::template Type>;
370	                using AssignLstNext = Append_t<AssignLst, NewCopyOut>;
371	                return Bind2OpAssign<
372	                    bufIds, BindLst, OutBindLst, AssignLstNext, Bind2ParamMap, Param2BufMap, BufId2ParamMap, pos + 1,
373	                    localVarIdx>();
374	            }
375	        } else { // OpAssign
376	            using Result = decltype(ReuseOrCreateLocalVar<pingId, B, OutBindLst, BufId2ParamMap, localVarIdx>());
377	            using AssignLhs = Get_t<Result, 0>;
378	            using BufId2ParamMapNext = Get_t<Result, 1>;
379	            constexpr auto updateParam2BufMap = Get_t<Result, 2>::value;
380	            constexpr auto localVarIdxNext = Get_t<Result, 3>::value;
381	            using AssignRhs = ReplaceOpArgs_t<Operation, BindAssignedToFinder<Bind2ParamMap>::template Type>;
382	            using AssignLstNext = Append_t<AssignLst, OpAssign<AssignLhs, AssignRhs>>;
383	            using Bind2ParamMapNext = Prepend_t<TypeList<B, AssignLhs>, Bind2ParamMap>;
384	            if constexpr (updateParam2BufMap) {
385	                using Param2BufMapNext = Append_t<
386	                    Param2BufMap,
387	                    ParamBufIdMap<
388	                        AssignLhs::number, IsParam_v<AssignLhs> ? BufType::PARAM : BufType::LOCAL_VAR, pingId, pongId>>;
389	                return Bind2OpAssign<
390	                    bufIds, BindLst, OutBindLst, AssignLstNext, Bind2ParamMapNext, Param2BufMapNext, BufId2ParamMapNext,
391	                    pos + 1, localVarIdxNext>();
392	            } else {
393	                return Bind2OpAssign<
394	                    bufIds, BindLst, OutBindLst, AssignLstNext, Bind2ParamMapNext, Param2BufMap, BufId2ParamMapNext,
395	                    pos + 1, localVarIdxNext>();
396	            }
397	        }
398	    } else {
399	        return TypeList<AssignLst, Param2BufMap>{};
400	    }
401	}
