416	template <typename ExprList /*TypeList*/>
417	struct ManualDag : DagBase<ExprList> {
418	private:
419	    using Base = DagBase<ExprList>;
420	
421	public:
422	    using AllLocalVars = LocalVars_t<ExprList>;
423	    // TypeList of ParamBufIdMap
424	    using BufMap = typename GenerateBufferId<Size_v<typename Base::AllParams>, Size_v<AllLocalVars>>::Type;
425	    // Get a type list of type lists of three items:
426	    //      (Param, FirstUseConst, LastUseConst)
427	    using ParamUseList = Map_t<FirstAndLastUseFinder<ExprList>::template Type, typename Base::AllParams>;
428	    using LocalVarUseList = Map_t<FirstAndLastUseFinder<ExprList>::template Type, AllLocalVars>;
429	
430	private:
431	    // For each input Param in ParamUseList, add an OpCopyIn before its first use.
432	    // Reverse order makes the result "look" better.
433	    constexpr static auto result1 = ForEach(Reverse_t<ParamUseList>{}, CopyInInserter{}, ExprList{});
434	
435	    // For each output Param in ParamUseList, add an OpCopyOut after its last use.
436	    constexpr static auto result2 = ForEach(ParamUseList{}, CopyOutInserter{}, result1);
437	
438	public:
439	    using ExprListWithCopyX = decltype(result2);
440	};
