51	template <size_t N, typename T, auto Usage, size_t R, typename From, typename To>
52	struct ReplaceExpr<Atvoss::Param<N, T, Usage, R>, From, To> {
53	    using Type = Atvoss::Param<N, T, Usage, R>;
54	};
