57	template <template <typename, typename> class Op, typename LHS, typename RHS, typename From, typename To>
58	struct ReplaceRecursive<Op<LHS, RHS>, From, To> {
59	    using newLhs = typename ReplaceExpr<LHS, From, To>::Type;
60	    using newRhs = typename ReplaceExpr<RHS, From, To>::Type;
61	    using Type = Op<newLhs, newRhs>;
62	};
