65	template <template <typename> class Op, typename Inner, typename From, typename To>
66	struct ReplaceRecursive<Op<Inner>, From, To> {
67	    using newInner = typename ReplaceExpr<Inner, From, To>::Type;
68	    using Type = Op<newInner>;
69	};
