72	template <template <auto, typename> class Op, auto N, typename Inner, typename From, typename To>
73	struct ReplaceRecursive<Op<N, Inner>, From, To> {
74	    using newInner = typename ReplaceExpr<Inner, From, To>::Type;
75	    using Type = Op<N, newInner>;
76	};
