103	template <template <typename, typename> class Op, typename LHS, typename RHS>
104	struct ExtractTypeListPostOrder<Op<LHS, RHS>, std::enable_if_t<IsBinaryOp_v<Op<LHS, RHS>>>> {
105	    using lhsList = typename ExtractTypeListPostOrder<LHS>::Type;
106	    using rhsList = typename ExtractTypeListPostOrder<RHS>::Type;
107	    using concatList = typename Atvoss::Util::Concatenate<
108	        typename std::conditional_t<
109	            Atvoss::Util::IsSpecializationOf_v<Atvoss::OpAssign, Op<LHS, RHS>>,
110	            typename Atvoss::Util::Concatenate<rhsList, lhsList>, // 赋值操作符：先右后左
111	            typename Atvoss::Util::Concatenate<lhsList, rhsList>  // 先左后右
112	            >::Type,
113	        std::conditional_t<
114	            Atvoss::Util::IsSpecializationOf_v<Atvoss::OpAndThen, Op<LHS, RHS>>, Atvoss::Util::TypeList<>,
115	            Atvoss::Util::TypeList<Op<LHS, RHS>>>>::Type;
116	    using Type = concatList;
117	};
