140	// LocalVar的number与其右边的表达式的映射关系
141	template <size_t ID, typename Expr>
142	struct VarDef {};
143	
144	// 查找变量定义
145	template <size_t ID, typename DefList>
146	struct FindVarDef;
147	
148	template <size_t ID>
149	struct FindVarDef<ID, TypeList<>> {
150	    using Type = void;
151	};
152	
153	template <size_t ID, typename Expr, typename... Rest>
154	struct FindVarDef<ID, TypeList<VarDef<ID, Expr>, Rest...>> {
155	    using Type = Expr;
156	};
157	
158	template <size_t ID, size_t OtherID, typename Expr, typename... Rest>
159	struct FindVarDef<ID, TypeList<VarDef<OtherID, Expr>, Rest...>> {
160	    using Type = typename FindVarDef<ID, TypeList<Rest...>>::Type;
161	};
162	
163	// 检查 LocalVar 是否会被后面的 Param 引用
164	template <size_t ID, typename StmtList>
165	struct IsLocalVarReferencedByParam;
166	
167	template <size_t ID>
168	struct IsLocalVarReferencedByParam<ID, TypeList<>> {
169	    static constexpr bool value = false;
170	};
171	
172	template <size_t ID, typename NextStmt, typename... OtherStmts>
173	struct IsLocalVarReferencedByParam<ID, TypeList<NextStmt, OtherStmts...>> {
174	    // 检查 NextStmt 是否是 OpAssign<Param<...>, LocalVar<ID, ...>>
175	    template <typename Stmt>
176	    struct CheckStmt;
177	
178	    template <size_t PID, typename PT, ParamUsage PU, size_t LID, typename LT, typename LSrc>
179	    struct CheckStmt<OpAssign<Param<PID, PT, PU>, LocalVar<LID, LT, LSrc>>> {
180	        static constexpr bool value = (LID == ID);
181	    };
182	
183	    template <typename Other>
184	    struct CheckStmt {
185	        static constexpr bool value = false;
186	    };
187	
188	    static constexpr bool current = CheckStmt<NextStmt>::value;
189	    static constexpr bool rest = IsLocalVarReferencedByParam<ID, TypeList<OtherStmts...>>::value;
190	    static constexpr bool value = current || rest;
191	};
