309	// ========================================================
310	// OptimizeWithLocalVars: 将中间结果缓存为 LocalVar
311	// ========================================================
312	template <typename ExprList, size_t LocalVarNumber, typename Processed>
313	struct OptimizeWithLocalVarsImpl;
314	
315	// 终止条件
316	template <size_t LocalVarNumber, typename Processed>
317	struct OptimizeWithLocalVarsImpl<Atvoss::Util::TypeList<>, LocalVarNumber, Processed> {
318	    using Type = Processed;
319	};
320	
321	// 主递归：处理第一个表达式
322	template <typename First, typename... Rest, size_t LocalVarNumber, typename Processed>
323	struct OptimizeWithLocalVarsImpl<Atvoss::Util::TypeList<First, Rest...>, LocalVarNumber, Processed> {
324	private:
325	    // 判断是否应该缓存
326	    static constexpr bool shouldCache = !Atvoss::IsParam_v<First>;
327	    static constexpr bool firstIsOpAssign = Atvoss::Util::IsSpecializationOf_v<Atvoss::OpAssign, First>;
328	    static constexpr auto NextLocalVarNumber = firstIsOpAssign ? LocalVarNumber : LocalVarNumber + 1;
329	
330	    // LocalVar 类型
331	    using localVarType = Atvoss::LocalVar<
332	        LocalVarNumber, typename First::RetType, Atvoss::Param<1ul, typename First::RetType, (Atvoss::ParamUsage)0>>;
333	
334	    // 构造赋值语句
335	    using assignmentType = std::conditional_t<firstIsOpAssign, First, Atvoss::OpAssign<localVarType, First>>;
336	
337	    template <typename Expr>
338	    using ReplaceOne = typename ReplaceExpr<Expr, First, localVarType>::Type;
339	    using updatedRest = Atvoss::Util::TypeList<ReplaceOne<Rest>...>;
340	
341	    // 下一步状态
342	    using nextProcessed = typename std::conditional_t<
343	        shouldCache, Atvoss::Util::Append<Processed, assignmentType>, Util::TypeWrapper<Processed>>::Type;
344	
345	    using nextState = std::conditional_t<
346	        shouldCache, OptimizeWithLocalVarsImpl<updatedRest, NextLocalVarNumber, nextProcessed>,
347	        OptimizeWithLocalVarsImpl<Atvoss::Util::TypeList<Rest...>, LocalVarNumber, nextProcessed>>;
348	
349	public:
350	    using Type = typename nextState::Type;
351	};
