414	// First为OpAssign直接跳过，对OpAssign的右边进行化简，
415	// 比如把OpAdd(LocalVar2, OpAssign(LocalVar1, OpMul(in1*in1)))
416	// 化简成OpAdd(LocalVar2, LocalVar1)
417	template <typename First, typename... Rest, typename Processed>
418	struct OptimizeBindBuffExprImpl<Atvoss::Util::TypeList<First, Rest...>, Processed> {
419	private:
420	    // 判断是否应该缓存
421	    static constexpr bool shouldCache = !Atvoss::IsParam_v<First>;
422	
423	    // LocalVar 类型
424	    using localVarType = First;
425	
426	    // 化简OpAssign：把OpAssign(LocalVar3, OpAdd(LocalVar2, OpAssign(LocalVar1, OpMul(in1*in1))))
427	    // 化简成：OpAssign(LocalVar3, OpAdd(LocalVar2, LocalVar1))
428	    using assignSimplified = std::conditional_t<
429	        Atvoss::Util::IsSpecializationOf_v<Atvoss::OpAssign, First>, TypeList<typename SimplifyAssign<First>::Type>,
430	        TypeList<>>;
431	
432	    // 下一步状态
433	    using nextProcessed = Atvoss::Util::Concatenate_t<Processed, assignSimplified>;
434	
435	    using nextState = OptimizeBindBuffExprImpl<Atvoss::Util::TypeList<Rest...>, nextProcessed>;
436	
437	public:
438	    using Type = typename nextState::Type;
439	};
