47	template <typename LocalVarList, typename TargetOp>
48	constexpr bool FindLocalVarIndex = false;
49	
50	template <typename TargetOp>
51	constexpr bool FindLocalVarIndex<TypeList<>, TargetOp> = false;
52	
53	template <typename Head, typename... Tail, typename TargetOp>
54	constexpr bool FindLocalVarIndex<TypeList<Head, Tail...>, TargetOp> =
55	    std::is_same_v<typename Head::Like, TargetOp> ? true : FindLocalVarIndex<TypeList<Tail...>, TargetOp>;
56	
57	template <typename LocalVarList, typename TargetOp>
58	constexpr size_t GetLocalVarIndex = 0;
59	
60	template <typename TargetOp>
61	constexpr size_t GetLocalVarIndex<TypeList<>, TargetOp> = 0;
62	
63	template <typename Head, typename... Tail, typename TargetOp>
64	constexpr size_t GetLocalVarIndex<TypeList<Head, Tail...>, TargetOp> =
65	    std::is_same_v<typename Head::Like, TargetOp> ? Head::number : GetLocalVarIndex<TypeList<Tail...>, TargetOp>;
