177	template <typename Head, typename... Tail, typename M, typename Expr>
178	constexpr auto FlattenTypeList(TypeList<Head, Tail...>, M map, Expr expr)
179	{
180	    static_assert(IsOpAssign_v<Head>, "Each one of TypeList must be a OpAssign");
181	
182	    auto [curMap, curExpr] = FlattenOpAssign(Head{}, map, expr);
183	    return FlattenTypeList(TypeList<Tail...>{}, curMap, curExpr);
184	}
185	/*--------------------------------------------------------------------------------------------------------------------*/
186	template <typename Expr>
187	constexpr auto FlattenExprRecursively(Expr expr)
188	{
189	    if constexpr (IsOpAssign_v<Expr>) {
190	        auto [map, finalExpr] = FlattenOpAssign(expr, TypeList<>{}, TypeList<>{});
191	        return finalExpr;
192	    } else if constexpr (IsTypeList_v<Expr>) {
193	        auto [map, finalExpr] = FlattenTypeList(expr, TypeList<>{}, TypeList<>{});
194	        return finalExpr;
195	    } else {
196	        static_assert(true, "Expr must be a OpAssign or TypeList");
197	    }
198	}
199	/*--------------------------------------------------------------------------------------------------------------------*/
