29	struct AllocInserter {
30	    template <typename T, typename ExprList>
31	    __host_aicore__ constexpr auto operator()(T, ExprList) const
32	    {
33	        using ParamUse = typename T::Type;
34	        using Param = Get_t<ParamUse, 0>;
35	        if constexpr (!std::is_scalar_v<typename Param::Type>) {
36	            constexpr auto firstUse = Get_t<ParamUse, 1>::value;
37	            using OldItem = Get_t<ExprList, firstUse>;
38	            using NewItem = OpAndThen<OpAlloc<Param>, OldItem>;
39	            return Set_t<ExprList, firstUse, NewItem>{};
40	        } else {
41	            return ExprList{};
42	        }
43	    }
44	};
