46	struct FreeInserter {
47	    template <typename T, typename ExprList>
48	    __host_aicore__ constexpr auto operator()(T, ExprList) const
49	    {
50	        using ParamUse = typename T::Type;
51	        using Param = Get_t<ParamUse, 0>;
52	        if constexpr (!std::is_scalar_v<typename Param::Type>) {
53	            constexpr auto lastUse = Get_t<ParamUse, 2>::value;
54	            using OldItem = Get_t<ExprList, lastUse>;
55	            using NewItem = OpAndThen<OldItem, OpFree<Param>>;
56	            return Set_t<ExprList, lastUse, NewItem>{};
57	        } else {
58	            return ExprList{};
59	        }
60	    }
61	};
