180	// Calculate Pong Buffer ID as per @bufferId and @pongOffset.
181	static constexpr int32_t CalcPongBufferId(
182	    int32_t bufferId, uint32_t bufferUsage, uint32_t pingPong, uint32_t pongOffset)
183	{
184	    if (pingPong > BUF_PONG) {
185	        // combined buffer wrapper.
186	        // bufferUsage/id/pingPong will always non-negative.
187	        if (pingPong == 0) {
188	            return 0;
189	        } else {
190	            const uint32_t id = static_cast<uint32_t>(bufferId) & BUF_COMBINE_MASK;
191	            const uint32_t usage = bufferUsage & BUF_COMBINE_MASK;
192	            const uint32_t pp = pingPong & BUF_COMBINE_MASK;
193	            const uint32_t currentId =
194	                pp == BUF_PING ? (bufferUsage == BUF_TEMP ? id : (id + pongOffset)) : (id - pongOffset);
195	            const int32_t idNext = static_cast<int32_t>(static_cast<uint32_t>(bufferId) >> BUF_COMBINE_SHIFT);
196	            const uint32_t usageNext = bufferUsage >> BUF_COMBINE_SHIFT;
197	            const uint32_t ppNext = pingPong >> BUF_COMBINE_SHIFT;
198	            return static_cast<int32_t>(
199	                static_cast<uint32_t>(CalcPongBufferId(idNext, usageNext, ppNext, pongOffset)) << BUF_COMBINE_SHIFT |
200	                currentId);
201	        }
202	    } else {
203	        // pure buffer wrapper
204	        return pingPong == BUF_PING ? ((bufferUsage == BUF_TEMP || bufferUsage == BUF_SCALAR) ?
205	                                           bufferId :
206	                                           (bufferUsage == BUF_PLACEHOLDER ? -1 : (bufferId + pongOffset))) :
207	                                      (bufferId - pongOffset);
208	    }
209	}
