525	/*
526	 * Generate buffer id of each Expression savedin @OpLst as per @memLvl
527	 * Template Arguments：
528	 *   1. OpLst: Ordered full Expression / Compute list
529	 *   2. OutLst: Full list of Output
530	 *   3. BufLstLst：Unused MTE2/MTE3/TmpBuffer List
531	 *   4. pongOffset: Offset of Pong buffer id to Ping buffer
532	 *   5. memLvl: memory level (policy) 0/1/2
533	 *   6. useNddma: whether use NDDMA from CopyInBrc operator
534	 *   7. cacheBrc: whether cache CopyInBrc & VecBrc operation outputs
535	 *   8. AllocLst: Allocated buffer list of `BufferWrapper` currently
536	 *   9. ToReleaseLst: To release list of `Mapping<Bind, TypeList<BufferWrapper...>>`
537	 *  10. scalarIdx: index or placehold of next `Scalar` operation output
538	 *  11. opPos: Position of current Expression / Compute
539	 * Return：
540	 *   1. 2*Size_v<OpLst> integer matrix as `const int32_t* const*`
541	 */
542	template <
543	    typename OpLst, typename OutLst, typename BufLstLst, uint32_t pongOffset, MemLevel memLvl = MemLevel::LEVEL_2,
544	    bool useNddma = true, bool cacheBrc = false, typename AllocLst = TypeList<>, typename ToReleaseLst = TypeList<>,
545	#ifdef __ATP_UT__
546	    int32_t scalarIdx = 50,
547	#else
548	    int32_t scalarIdx = 0,
549	#endif
550	    std::size_t opPos = 0>
551	static constexpr const int32_t* const* GenerateBufferIdOrder()
