565	            if constexpr (ConnectToAny_v<OutLst, Op>) {
566	                // if CopyInBrc -> CopyOut, should use MTE3
567	                using NextLst = AllocMte3_t<NextLst0, memLvl, cacheBrc>;
568	                using Mte3 = Get_t<NextLst, BUF_ALLOCATED_IDX>;
569	                // add to alloc list
570	                using Buf = CombinedBufferWrappers<Mte3, Mte2>;
571	                using AllocLstNext = Append_t<AllocLst, Buf>;
572	                using ToReleaseLstNext = Append_t<ToReleaseLst, Mapping<Op, Mte3, Mte2>>;
573	                // next
574	                return GenerateBufferIdOrder<
