576	                    scalarIdx, opPos + 1>();
577	            } else {
578	                using NextLst = AllocTempBuffer_t<NextLst0, memLvl, cacheBrc>;
579	                using Tmp = Get_t<NextLst, BUF_ALLOCATED_IDX>;
580	                // add to alloc list
